  if(cov.includes('Innere Strukturen / Volumen'))canonical.push('Erfassungsumfang: innere Strukturen / Volumen','innere Strukturen / Volumen');
  if(ops.includes('Verlässlich messen'))canonical.push('Operation: verlässlich messen','Maßhaltigkeit und metrische Auswertbarkeit');
  if(ops.includes('Formen oder Merkmale vergleichen'))canonical.push('Operation: Formen oder Merkmale vergleichen');
  if(ops.includes('Zustände vergleichen'))canonical.push('Zustandsvergleich / Zustandsversionen');
  if(ops.includes('Annotieren / segmentieren'))canonical.push('Operation: annotieren / segmentieren');
  if(ops.includes('Algorithmisch / maschinell auswerten'))canonical.push('Operation: algorithmisch / maschinell auswerten');
  if(ops.includes('Neue Derivate erzeugen'))canonical.push('Operation: neue Derivate erzeugen');
