function renderModes(){const el=$('#modeGrid');el.innerHTML=Object.entries(D.modes).map(([k,m])=>`<label class="mode-card ${state.meta.mode===k?'selected':''}"><input type="radio" name="mode" value="${k}" ${state.meta.mode===k?'checked':''}><strong>${esc(m.label)}</strong><span>${esc(m.description)}</span></label>`).join('');$$('input[name="mode"]').forEach(r=>r.addEventListener('change',e=>{if(state.workflow.started){e.target.checked=state.meta.mode===e.target.value;return;}state.meta.mode=e.target.value;save();renderAll();}));$('#startBtn').disabled=!state.meta.mode;$('#startBtn').textContent=state.workflow.activeEdit?.target==='intro'?'Änderungen abschließen & weiter →':state.workflow.started?'Weiter zur Nutzung →':'Anwendung starten →';applyLock('intro');}
function useBlock(u,index,isReuse=false){
 const kind=isReuse?'reuse':'use',ref=`${isReuse?'NH':mode().usePrefix}${index+1}`,catalog=D.usageCatalog,preset=usageCatalog(u.area),ownArea=u.area&&!preset?u.area:'',areaKey=`use:${kind}:${index}:area`,areaSummary=u.area?`<span class="guided-status done">✓ ${esc(u.area)}</span>`:'<span class="guided-status pending">offen</span>';
 return `<article class="use-block"><div class="block-head"><div><strong>${ref}</strong><span>${isReuse?'Weitere bewusst berücksichtigte Nutzung':mode().useLabel}</span></div>${(isReuse||state.b1.uses.length>1)?`<button class="remove-row" type="button" data-remove-${kind}="${index}">×</button>`:''}</div><div class="block-body"><details class="guided-block" data-expandable="true" data-panel-key="${areaKey}" ${panelOpen(areaKey,!u.area)?'open':''}><summary><span><b>Nutzung</b><small>Einfachauswahl</small></span>${areaSummary}</summary><div class="guided-body">${u.area?`<div class="selected-tag-row"><span class="selection-tag"><span class="tag-check">✓</span>${esc(u.area)}${preset?`<button type="button" class="option-info selected-use-info" ${optionInfoAttr(preset.description||'')} aria-label="Nutzung erklären">ⓘ</button>`:''}</span></div>`:''}<p class="microcopy">Die Nutzung beschreibt den fachlichen Zweck. Im nächsten Schritt werden die ausgewählten Nutzungen gemeinsam in konkrete Anforderungen an Objektinformationen, räumlichen Geltungsbereich und mögliche Datenhandlungen übersetzt.</p><div class="picker-line">${ownPicker(`${areaKey}:own`,'Eigene Nutzung formulieren','data-own-area',`${kind}:${index}`,ownArea,'Eigene Angabe')}${usageChoiceButtons(u.area&&preset?u.area:'','data-area-chip',`${kind}:${index}`)}</div>${ownArea?freeRuleStatusHtml(ownArea):''}</div></details>${isReuse?optionalDetails('Begründung für die Berücksichtigung (optional)',`<label>Begründung / Anmerkung<textarea rows="3" data-reuse-reason="${index}">${esc(u.reason||'')}</textarea></label>`,!!u.reason):''}</div></article>`;
}
function renderUses(){
 const p=planning(),m=mode();setText('#modeEyebrow1',`${m.label} · ${m.short}`);setText('#usesMainTitle',p?'Nutzung und Nachnutzungshorizont':'Zielnutzung');setText('#primaryUseHeading',p?'Wofür soll das Fundobjekt dokumentiert werden?':'Für welche Nutzung soll der vorhandene Datenbestand bewertet werden?');
 setText('#usesPurpose',p?'Festlegen, wofür die neue Dokumentation geplant wird. Aus den ausgewählten Nutzungen werden anschließend die benötigten Objektinformationen, Bereiche und Datenhandlungen abgeleitet.':'Festlegen, für welche Nutzung der vorhandene Datenbestand bewertet wird. Dies kann die ursprünglich vorgesehene Nutzung oder eine neue beziehungsweise später hinzugekommene Zielnutzung sein.');
 const qs=$('#primaryUseSupport');if(qs)qs.textContent='Mehrfachauswahl möglich.';
 const eb=$('#evaluationBasisWrap');eb.classList.toggle('hidden',p);if(!p)eb.innerHTML=`<div class="field-section"><span class="field-label">Welcher Bewertungsmaßstab soll verwendet werden?</span><p class="microcopy">Ein vorhandener Bestand kann sowohl auf seinen ursprünglichen Erzeugungszweck als auch auf eine neue beziehungsweise spätere Nutzung geprüft werden.</p><div class="mode-grid evaluation-choice-grid"><label class="mode-card ${state.b1.evaluationBasis==='original'?'selected':''}"><input type="radio" name="evaluationBasis" value="original" ${state.b1.evaluationBasis==='original'?'checked':''}><strong>Ursprünglich vorgesehene Nutzung prüfen</strong><span>Es wird bewertet, ob der Bestand für die Nutzung geeignet ist, für die er ursprünglich erzeugt wurde.</span></label><label class="mode-card ${state.b1.evaluationBasis==='new'?'selected':''}"><input type="radio" name="evaluationBasis" value="new" ${state.b1.evaluationBasis==='new'?'checked':''}><strong>Neue / spätere Zielnutzung prüfen</strong><span>Die heute zu prüfende Nutzung bestimmt das Soll; der ursprüngliche Zweck dient nur der Einordnung.</span></label></div></div>`;
 $('#useBlocks').innerHTML=state.b1.uses.map((u,i)=>useBlock(u,i,false)).join('');
 const reuseCard=$('#reuseCard');if(reuseCard)reuseCard.classList.toggle('hidden',!p);if(p){$('#reuseBlocks').innerHTML=state.b1.reuse.length?state.b1.reuse.map((u,i)=>useBlock(u,i,true)).join(''):`<div class="task-empty">Noch keine spätere Nutzung bewusst offengehalten.</div>`;}else state.b1.reuse=[];
 $('#originalPurposeWrap').classList.toggle('hidden',p||state.b1.evaluationBasis!=='new');val('#originalPurpose',state.b1.originalPurpose);val('#boundary',state.b1.boundary);
 setText('#usesResult',p?'Vorgesehene Nutzung(en) und gegebenenfalls bewusst berücksichtigte spätere Nutzungen bilden den Nutzungsrahmen. Im nächsten Schritt werden daraus gemeinsame Anforderungen konkretisiert.':state.b1.evaluationBasis==='original'?'Die ursprünglich vorgesehene Nutzung bildet den Bewertungsmaßstab. Weitere Zielnutzungen können als zusätzliche Nutzungen angelegt werden.':'Die festgelegte neue beziehungsweise spätere Zielnutzung bildet den Bewertungsmaßstab; der ursprüngliche Zweck bleibt als Kontext getrennt.');bindUseEvents();bindRenderedUI('uses');applyLock('uses');queueValidation('uses');
}
function collection(kind){return kind==='reuse'?state.b1.reuse:state.b1.uses;}
