 $$('input[name="evaluationBasis"]').forEach(e=>e.addEventListener('change',x=>{state.b1.evaluationBasis=x.target.value;renderUses();save();}));
 $$('[data-area-chip]').forEach(b=>b.addEventListener('click',()=>{const[k,i]=b.dataset.areaChip.split(':'),u=collection(k)[+i];u.area=b.value;renderUses();save();}));
 $$('[data-own-area]').forEach(e=>e.addEventListener('change',x=>{const[k,i]=x.target.dataset.ownArea.split(':'),u=collection(k)[+i],v=x.target.value.trim();if(!v)return;u.area=v;renderUses();save();}));
