function reqContextText(g){const ref=refByUseId(g.useId),c=state.b2.objectContext||blankObjectContext(),parts=[ref?.area||'',...(c.materialGroups||[]),c.materialOwn];if(g.infoDecision==='yes')parts.push(...g.informations,g.infoOwn);if(g.featureDecision==='yes')parts.push(...g.features,g.featureOwn);if(c.conditionDecision==='yes')parts.push(...c.conditions,c.conditionOwn);return parts.filter(Boolean).join(' ').toLowerCase();}
function keywordGroupMatches(group,text){const t=normMatch(text);return (group||[]).some(k=>t.includes(normMatch(k)));}
function structuredGuideMatch(row,text,{informations=[],area='',selectedForms=[]}={}){const selected=selectedForms||[];if((row.requiredSelectedForms||[]).length&&!row.requiredSelectedForms.some(f=>selected.some(x=>exactMatch([f],x))))return false;if((row.allSelectedForms||[]).length&&row.allSelectedForms.every(f=>selected.some(x=>exactMatch([f],x))))return true;const directInfo=(informations||[]).some(v=>exactMatch(row.informationMatches,v)),directArea=exactMatch(row.areaMatches,area),directForm=selected.some(f=>exactMatch(row.selectedFormMatches,f));if(directInfo||directArea||directForm)return true;if((row.allKeywordGroups||[]).length&&!row.allKeywordGroups.every(g=>keywordGroupMatches(g,text)))return false;if((row.allKeywordGroups||[]).length)return true;const n=Number(row.minContextMatches||1);return (row.contextKeywords||[]).length&&contextHitCount(row,text)>=n;}
function guideTrace(row,text,{informations=[],area='',selectedForms=[],freeTexts=[]}={}){const triggers=[];const info=(informations||[]).find(v=>exactMatch(row.informationMatches,v));if(info)triggers.push(`konkretisierte Anforderung „${info}“`);if(area&&exactMatch(row.areaMatches,area))triggers.push(`Nutzung „${area}“`);const form=(selectedForms||[]).find(f=>exactMatch(row.selectedFormMatches,f)||exactMatch(row.requiredSelectedForms,f));if(form)triggers.push(`Dokumentationsform „${form}“`);const nt=normMatch(text);const hits=uniq((row.contextKeywords||[]).filter(k=>nt.includes(normMatch(k))));for(const hit of hits.slice(0,3)){const own=(freeTexts||[]).find(t=>normMatch(t).includes(normMatch(hit)));triggers.push(own?`freie Angabe „${own}“ → erkannt: ${hit}`:`Kontext: ${hit}`);}for(const group of (row.allKeywordGroups||[])){const hit=(group||[]).find(k=>nt.includes(normMatch(k)));if(hit){const own=(freeTexts||[]).find(t=>normMatch(t).includes(normMatch(hit)));triggers.push(own?`freie Angabe „${own}“ → erkannt: ${hit}`:`Kontext: ${hit}`);}}const condition=row.information||row.requirement||row.label||row.use||'passende Orientierungsregel';const why=row.objectNote||row.contribution||row.note||row.check||row.function||'Die hinterlegte Orientierungsregel passt zum dokumentierten Kontext.';return `Regel: ${row.id||'ohne ID'}${row.source?` · Grundlage: ${row.source}`:''}\nAuslöser: ${uniq(triggers).join(' · ')||'Kombination der bisherigen Angaben'}\nErkannte Regelbedingung: ${condition}\nBegründung: ${why}`;}
function allOrientationRules(){return [...(D.documentationFormGuide||[]),...(D.qualityOrientationGuide||[]),...(D.procedureGuide||[]),...(D.dataComponentGuide||[])];}
function freeTextRuleHits(text){const n=normMatch(text);if(!n)return[];return allOrientationRules().filter(r=>{const vals=[...(r.contextKeywords||[]),...(r.informationMatches||[]),...(r.areaMatches||[]),...(r.selectedFormMatches||[]),...(r.requiredSelectedForms||[]),...(r.requirementKeywords||[]),...(r.operationMatches||[]),r.information,r.requirement,r.label,r.use].filter(Boolean);return vals.some(v=>{const x=normMatch(v);return x&&((n.length>=4&&x.includes(n))||(x.length>=4&&n.includes(x)));});});}
function freeRuleStatusHtml(text){if(!String(text||'').trim())return'';const hits=freeTextRuleHits(text);return hits.length?`<div class="free-rule-status hit"><strong>Wird bei den Orientierungsvorschlägen berücksichtigt.</strong><span>Für diese freie Angabe wurde ein passender Bezug in der hinterlegten Wissensbasis gefunden. Prüfen Sie die daraus hervorgehobenen Vorschläge fachlich.</span></div>`:`<div class="free-rule-status miss"><strong>Für diese freie Angabe sind derzeit keine automatischen Orientierungsvorschläge hinterlegt.</strong><span>Die Angabe bleibt Bestandteil des Falls und kann fachlich berücksichtigt werden.</span></div>`;}
function recommendedFormDetails(g){const ref=refByUseId(g.useId),t=reqContextText(g),ctx={informations:g.infoDecision==='yes'?[...(g.informations||[]),g.infoOwn].filter(Boolean):[],area:ref?.area||'',freeTexts:[g.infoOwn,g.featureOwn,(state.b2.objectContext||{}).materialOwn,(state.b2.objectContext||{}).conditionOwn].filter(Boolean)},rows=(D.documentationFormGuide||[]).filter(r=>structuredGuideMatch(r,t,ctx)),tips={};for(const r of rows)for(const f of (r.forms||[]))if(!tips[f])tips[f]=guideTrace(r,t,ctx);return {forms:uniq(rows.flatMap(r=>r.forms||[])).filter(x=>D.documentationForms.some(f=>f.label===x)),tips};}
