function renderInventory(){const statuses=[['present','belegt / vorhanden'],['absent','nachweislich nicht vorhanden'],['unclear','ungeklärt'],['inaccessible','derzeit nicht zugänglich'],['conflict','widersprüchliche Angaben']];$('#inventoryList').innerHTML=`<div class="optional-section-note">Die Bestandsaufnahme kann so weit ausgefüllt werden, wie es für die Bewertung hilfreich ist. Keines dieser Detailfelder ist verpflichtend.</div><div class="accordion-stack">${D.retrospectiveInventory.map((a,i)=>{const q=state.b4.evaluation.inventory[i]||{status:'',evidence:'',note:''};return `<details class="detail-accordion" data-expandable="true" data-inv-row="${i}" ${(q.status||q.evidence||q.note)?'open':''}><summary><span>${esc(a)}</span><small>${esc(inventoryStatus(q.status)||'optional')}</small></summary><div class="detail-accordion-body"><div class="status-radios wrap">${statuses.map(x=>`<label class="status-choice ${q.status===x[0]?'selected':''}"><input type="radio" name="inv-${i}" data-inv-status="${i}" value="${x[0]}" ${q.status===x[0]?'checked':''}>${x[1]}</label>`).join('')}</div>${optionalDetails('Zusätzliche Dokumentation (optional)',`<label>Nachweisgrundlage<textarea rows="3" data-inv-evidence="${i}">${esc(q.evidence||'')}</textarea></label><label>Bemerkung / offene Frage<textarea rows="3" data-inv-note="${i}">${esc(q.note||'')}</textarea></label>`,!!(q.evidence||q.note))}</div></details>`;}).join('')}</div>`;$$('[data-inv-status]').forEach(e=>e.addEventListener('change',x=>{state.b4.evaluation.inventory[x.target.dataset.invStatus].status=x.target.value;renderInventory();save();}));$$('[data-inv-evidence]').forEach(e=>e.addEventListener('input',x=>{state.b4.evaluation.inventory[x.target.dataset.invEvidence].evidence=x.target.value;save();}));$$('[data-inv-note]').forEach(e=>e.addEventListener('input',x=>{state.b4.evaluation.inventory[x.target.dataset.invNote].note=x.target.value;save();}));}
