function actualRequirementItem(ref,a,x,levels){const val=state.b4.actual[x.actualKey]||blankActual(x.actualKey);return `<div class="quality-requirement compact-split" data-actual-key="${esc(x.actualKey)}"><div class="selected-title"><strong>${esc(qualityReqLabel(a,x.requirement))}</strong><button type="button" class="option-info standalone-info" ${optionInfoAttr(qualityReqInfo(a,x.requirement))}>ⓘ</button><small>Geltungsbereich: ${esc(x.scopeLabel)}</small></div><div class="split-level-choice"><div class="level-radios compact-common-levels">${levels.map(v=>`<label class="level-choice ${val.level===v?'selected':''}"><input type="radio" name="actual-${ref.useId}-${a}-${esc(x.actualKey)}" data-actual-level="${esc(x.actualKey)}" data-actual-owner="${ref.useId}:${a}" value="${v}" ${val.level===v?'checked':''}><b>${esc(qLevelLabel(v))}</b><span>${v==='0'?'Die relevante Eigenschaft ist nicht einmal grundlegend vorhanden.':v==='n.b.'?'Relevant, aber am vorhandenen Bestand nicht belastbar beurteilbar.':esc(D.qualityAreas[a].levels[v]||'')}</span></label>`).join('')}</div></div>${optionalDetails('Grundlage / Unsicherheit (optional)',`<label>${planning()?'Grundlage der Einschätzung':'Nachweisgrundlage'}<textarea rows="2" data-actual-evidence="${esc(x.actualKey)}">${esc(val.evidence)}</textarea></label><label>Bekannte Unsicherheit / Einschränkung<textarea rows="2" data-actual-uncertainty="${esc(x.actualKey)}">${esc(val.uncertainty)}</textarea></label>`,!!(val.evidence||val.uncertainty))}</div>`;}
