 $$('[data-actual-detail-toggle]').forEach(b=>b.addEventListener('click',()=>{const[useId,a]=b.dataset.actualDetailToggle.split(':'),ui=actualUiState(useId,a),items=actualItemsForUseArea(useId,a);if(ui.split){items.forEach(i=>{if(!state.b4.actual[i.actualKey])state.b4.actual[i.actualKey]=blankActual(i.actualKey);state.b4.actual[i.actualKey].level='';});ui.split=false;}else{ui.split=true;}rememberPanel(`actualarea:${useId}:${a}`,true);renderActualProfiles();save();}));
