function commonAreaConsequence(a){const items=areaIssueItems(a);if(!items.length)return {selected:[],own:'',note:'',details:{}};const vals=items.map(x=>state.b5.consequences[x.key]||{selected:[],own:'',note:'',details:{}}),shape=v=>JSON.stringify({selected:v.selected||[],own:v.own||'',note:v.note||'',details:v.details||{}}),first=shape(vals[0]);return vals.every(v=>shape(v)===first)?vals[0]:null;}
