function consequenceAreaCard(a){const items=areaIssueItems(a.area),ui=consequenceUiState(a.area),common=commonAreaConsequence(a.area);if(!common)ui.split=true;const opts=D.consequences[planning()?'planning':'evaluation'];return `<details class="consequence-card guided-block" data-expandable="true" open><summary class="block-head"><div><strong>${esc(a.label)}</strong><span>${a.deviation?`${a.deviation} Abweichung${a.deviation===1?'':'en'}`:''}${a.deviation&&a.unknown?' · ':''}${a.unknown?`${a.unknown} nicht beurteilbar`:''}</span></div></summary><div class="guided-body">${ui.split?`<div class="split-quality-list">${items.map(x=>consequenceCard(x)).join('')}</div><button type="button" class="text-button" data-cons-area-mode="${a.area}" value="common">Folgerung wieder gemeinsam festlegen</button>`:`<span class="field-label">Welche Folgerung ergibt sich für diesen Qualitätsbereich?</span>${selectedTags(common?.selected||[],common?.own||'')}<div class="picker-line">${suggestionButtons(opts,common?.selected||[],'data-cons-area-toggle',a.area)}${ownPicker(`cons-area:${a.area}`,'Eigene Folgerung','data-cons-area-own',a.area,common?.own||'','Eigene Angabe')}</div><div class="consequence-detail-fields">${consequenceDetailFields(common?.selected||[],common?.details||{},'area',a.area)}</div>${optionalDetails('Weitere Folgerungen oder Begründungen (optional)',`<label>Angabe<textarea rows="2" data-cons-area-note="${a.area}">${esc(common?.note||'')}</textarea></label>`,!!common?.note)}<button type="button" class="text-button" data-cons-area-mode="${a.area}" value="split">Für einzelne Abweichungen getrennt festlegen</button>`}</div></details>`;}
