function applyLock(k){
 const screen=$('#'+k);if(!screen)return;const slot=screen.querySelector(`[data-lock-slot="${k}"]`);const active=state.workflow.activeEdit?.target===k,locked=k==='intro'?state.workflow.started&&!active:state.workflow.completed[k]&&!active,stale=k==='intro'?false:state.workflow.stale[k];
 if(slot){if(active)slot.innerHTML=`<div class="revision-banner active"><div><strong>Änderung wird dokumentiert</strong><span>${esc(state.workflow.activeEdit.source)}</span></div><button class="secondary small cancel-revision" type="button">Änderung verwerfen</button></div>`;else if(stale)slot.innerHTML=`<div class="revision-banner stale"><div><strong>Erneute Prüfung erforderlich</strong><span>Eine frühere fachliche Festlegung wurde geändert. Prüfen Sie diesen Abschnitt erneut und schließen Sie ihn anschließend wieder ab.</span></div></div>`;else if(locked)slot.innerHTML=`<div class="revision-banner locked"><div><strong>${k==='intro'?'Vorgang gestartet':'Abschnitt abgeschlossen'}</strong><span>${k==='intro'?'Stammdaten sind festgeschrieben; die Anwendungsrichtung bleibt für diesen Vorgang unverändert. Korrekturen können direkt durch Anklicken eines Feldes gestartet werden.':'Der Stand ist festgeschrieben. Sie können jederzeit zurückkehren und Angaben ändern. Jede umgesetzte Änderung wird automatisch protokolliert.'}</span></div><button class="secondary small unlock-section" data-unlock="${k}" type="button">Änderung starten</button></div>`;else slot.innerHTML='';}
 const controls=[...screen.querySelectorAll('input,textarea,select')];controls.forEach(c=>{if(locked)c.setAttribute('aria-disabled','true');else c.removeAttribute('aria-disabled');});screen.classList.toggle('screen-locked',locked);
 const next=screen.querySelector('.complete-next');if(next){if(!next.dataset.defaultText)next.dataset.defaultText=next.textContent;next.textContent=active?'Änderungen abschließen & weiter →':locked?'Weiter →':next.dataset.defaultText;}
 screen.querySelectorAll('.unlock-section').forEach(b=>b.addEventListener('click',()=>openEditDialog(b.dataset.unlock,null)));screen.querySelectorAll('.cancel-revision').forEach(b=>b.addEventListener('click',()=>{if(confirm('Die begonnenen Änderungen verwerfen und den vorherigen Stand wiederherstellen?'))cancelActiveEdit();}));
}
