 const context=editActionContext(target),impact=editImpact(k,target),resume=()=>{beginEdit(k,impact,`Direkte Änderung: ${context}`);setTimeout(()=>{if(!target)return;if(target.matches?.('textarea,input[type="text"],input[type="date"]'))target.focus();else target.click?.();},0);};
 if(state.workflow.revisionNoticeDismissed)return resume();
